/**
 * WebSocket Adapter for Mini Program
 * 封装微信小程序 WebSocket API，支持 Socket.IO 协议
 */

declare const wx: any;
declare const SocketTask: any;

export interface WebSocketOptions {
  url: string;
  protocols?: string[];
  timeout?: number;
}

export interface WebSocketMessage {
  data: string | ArrayBuffer;
}

/**
 * WebSocket 适配器类
 */
export class MiniProgramWebSocket {
  private socketTask: any = null;
  private url: string = '';
  private protocols: string[] = [];
  private isConnected: boolean = false;
  private isClosed: boolean = false;

  // 事件回调
  private onOpenCallback: ((event: any) => void) | null = null;
  private onMessageCallback: ((event: WebSocketMessage) => void) | null = null;
  private onErrorCallback: ((event: any) => void) | null = null;
  private onCloseCallback: ((event: any) => void) | null = null;

  constructor(url: string, protocols?: string | string[]) {
    this.url = url;
    this.protocols = Array.isArray(protocols) ? protocols : protocols ? [protocols] : [];
  }

  /**
   * 连接到 WebSocket 服务器
   */
  connect(options?: { timeout?: number }): Promise<void> {
    return new Promise((resolve, reject) => {
      if (this.socketTask) {
        resolve();
        return;
      }

      const task = wx.connectSocket({
        url: this.url,
        protocols: this.protocols.length > 0 ? this.protocols : undefined,
        timeout: options?.timeout || 30000
      });

      task.onOpen((event: any) => {
        this.isConnected = true;
        this.onOpenCallback?.(event);
        resolve();
      });

      task.onMessage((event: WebSocketMessage) => {
        this.onMessageCallback?.(event);
      });

      task.onError((event: any) => {
        this.isConnected = false;
        this.onErrorCallback?.(event);
        reject(event);
      });

      task.onClose((event: any) => {
        this.isConnected = false;
        this.isClosed = true;
        this.onCloseCallback?.(event);
      });

      this.socketTask = task;
    });
  }

  /**
   * 发送数据
   */
  send(data: string | ArrayBuffer): void {
    if (!this.socketTask || !this.isConnected) {
      console.warn('[WebSocket] Not connected, cannot send message');
      return;
    }

    let sendData: string | ArrayBuffer | Uint8Array = data;

    // 如果是 ArrayBuffer，转换为 Uint8Array
    if (data instanceof ArrayBuffer) {
      sendData = new Uint8Array(data);
    }

    this.socketTask.send({
      data: sendData,
      fail: (err: any) => {
        console.error('[WebSocket] Send error:', err);
      }
    });
  }

  /**
   * 关闭连接
   */
  close(code?: number, reason?: string): void {
    if (!this.socketTask) return;

    this.isConnected = false;
    this.isClosed = true;

    this.socketTask.close({
      code: code || 1000,
      reason: reason || 'Normal closure'
    });

    this.socketTask = null;
  }

  /**
   * 设置打开回调
   */
  onOpen(callback: (event: any) => void): void {
    this.onOpenCallback = callback;
  }

  /**
   * 设置消息回调
   */
  onMessage(callback: (event: WebSocketMessage) => void): void {
    this.onMessageCallback = callback;
  }

  /**
   * 设置错误回调
   */
  onError(callback: (event: any) => void): void {
    this.onErrorCallback = callback;
  }

  /**
   * 设置关闭回调
   */
  onClose(callback: (event: any) => void): void {
    this.onCloseCallback = callback;
  }

  /**
   * 获取连接状态
   */
  getReadyState(): number {
    if (this.isClosed) return 3; // CLOSED
    if (this.isConnected) return 1; // OPEN
    return 0; // CONNECTING
  }

  /**
   * 是否已连接
   */
  get isOpen(): boolean {
    return this.isConnected && !this.isClosed;
  }
}

/**
 * 创建 WebSocket 连接
 */
export function createWebSocket(url: string, protocols?: string | string[]): MiniProgramWebSocket {
  return new MiniProgramWebSocket(url, protocols);
}

/**
 * Socket.IO 适配器
 * 基于原生 WebSocket 封装
 */
export class SocketIOAdapter {
  private ws: MiniProgramWebSocket | null = null;
  private url: string = '';
  private namespace: string = '/';
  private connected: boolean = false;
  private eventHandlers: Map<string, Set<Function>> = new Map();
  private ackCallbacks: Map<number, Function> = new Map();
  private messageId: number = 0;

  constructor(url: string, options?: { namespace?: string }) {
    this.url = url;
    this.namespace = options?.namespace || '/';
  }

  /**
   * 连接到 Socket.IO 服务器
   */
  connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      // 构建 Socket.IO URL
      const socketUrl = `${this.url}?EIO=4&transport=websocket&t=${Date.now()}`;

      this.ws = new MiniProgramWebSocket(socketUrl);

      this.ws.onOpen(() => {
        this.connected = true;
        this.emit('connect');
        resolve();
      });

      this.ws.onMessage((event) => {
        this.handleMessage(event.data);
      });

      this.ws.onError((err) => {
        console.error('[SocketIO] Error:', err);
        reject(err);
      });

      this.ws.onClose(() => {
        this.connected = false;
        this.emit('disconnect');
      });

      this.ws.connect().catch(reject);
    });
  }

  /**
   * 处理 Socket.IO 协议消息
   */
  private handleMessage(data: string): void {
    // 解析 Socket.IO 协议
    // 格式: <message type><message id?>[<data>]
    const type = data.charAt(0);

    switch (type) {
      case '0': // Open
        break;
      case '2': // Ping
        this.sendPacket('3'); // Pong
        break;
      case '4': // Message
        const subtype = data.charAt(1);
        if (subtype === '0') { // Connect
          this.emit('connect');
        } else if (subtype === '2') { // Disconnect
          this.emit('disconnect');
        } else if (subtype === '4') { // Event
          this.parseEvent(data.substring(2));
        } else if (subtype === '6') { // Ack
          this.parseAck(data.substring(2));
        }
        break;
      default:
        console.log('[SocketIO] Unknown message type:', type);
    }
  }

  /**
   * 解析事件消息
   */
  private parseEvent(data: string): void {
    try {
      const parsed = JSON.parse(data);
      const eventName = parsed[0];
      const eventData = parsed[1];
      this.emit(eventName, eventData);
    } catch (e) {
      console.error('[SocketIO] Failed to parse event:', e);
    }
  }

  /**
   * 解析 Ack 响应
   */
  private parseAck(data: string): void {
    try {
      const parsed = JSON.parse(data);
      const ackId = parsed[0];
      const ackData = parsed[1];
      const callback = this.ackCallbacks.get(ackId);
      if (callback) {
        callback(ackData);
        this.ackCallbacks.delete(ackId);
      }
    } catch (e) {
      console.error('[SocketIO] Failed to parse ack:', e);
    }
  }

  /**
   * 发送 Socket.IO 数据包
   */
  private sendPacket(type: string, data?: string): void {
    if (!this.ws || !this.connected) {
      console.warn('[SocketIO] Not connected');
      return;
    }
    this.ws.send(data ? `${type}${data}` : type);
  }

  /**
   * 发送事件
   */
  emit(event: string, data?: any, callback?: Function): void {
    if (!this.connected) {
      console.warn('[SocketIO] Not connected, cannot emit event:', event);
      return;
    }

    const packetId = ++this.messageId;
    const payload: any[] = [event];

    if (data !== undefined) {
      payload.push(data);
    }

    const packetData = JSON.stringify(packetId >= 0 ? [payload, packetId] : payload);
    this.sendPacket('42', packetData);

    // 注册 Ack 回调
    if (callback && packetId >= 0) {
      this.ackCallbacks.set(packetId, callback);
    }
  }

  /**
   * 监听事件
   */
  on(event: string, callback: Function): void {
    if (!this.eventHandlers.has(event)) {
      this.eventHandlers.set(event, new Set());
    }
    this.eventHandlers.get(event)!.add(callback);
  }

  /**
   * 取消监听
   */
  off(event: string, callback?: Function): void {
    if (!callback) {
      this.eventHandlers.delete(event);
    } else {
      this.eventHandlers.get(event)?.delete(callback);
    }
  }

  /**
   * 触发事件
   */
  private emit(event: string, data?: any): void {
    const handlers = this.eventHandlers.get(event);
    if (handlers) {
      handlers.forEach(callback => {
        try {
          callback(data);
        } catch (e) {
          console.error('[SocketIO] Event handler error:', e);
        }
      });
    }
  }

  /**
   * 关闭连接
   */
  disconnect(): void {
    if (this.ws) {
      this.sendPacket('1'); // Disconnect
      this.ws.close();
      this.ws = null;
    }
    this.connected = false;
  }

  /**
   * 获取连接状态
   */
  get connected(): boolean {
    return this.connected;
  }
}

// Socket.IO factory (兼容原有 API)
const socketIOInstances: Map<string, SocketIOAdapter> = new Map();

export function io(url: string, options?: any): SocketIOAdapter {
  const key = options?.path || url;

  if (socketIOInstances.has(key)) {
    return socketIOInstances.get(key)!;
  }

  const instance = new SocketIOAdapter(url, options);
  socketIOInstances.set(key, instance);

  return instance;
}

export default {
  MiniProgramWebSocket,
  createWebSocket,
  SocketIOAdapter,
  io
};
