/**
 * Canvas Adapter for Mini Program
 * 封装微信小程序 canvas 相关 API，提供 WebGL 渲染支持
 */

declare const wx: any;

export interface CanvasAdapterOptions {
  type?: '2d' | 'webgl' | 'webgl2';
  canvasId: string;
  width?: number;
  height?: number;
}

export interface CanvasContext {
  canvas: any;
  getContext: (type: string) => any;
  width: number;
  height: number;
}

export interface WebGLRenderingContextExtended extends WebGLRenderingContext {
  // 小程序扩展属性
  canvas: any;
}

/**
 * 创建 Canvas 适配器
 */
export function createCanvasAdapter(options: CanvasAdapterOptions): CanvasContext {
  const { canvasId, width = 375, height = 667 } = options;

  // 小程序 canvas 组件
  const canvas = wx.createCanvas(canvasId, {
    type: options.type || 'webgl'
  });

  // 设置尺寸
  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }

  return {
    canvas,
    getContext: (type: string) => {
      return canvas.getContext(type);
    },
    width: canvas.width,
    height: canvas.height
  };
}

/**
 * 获取 WebGL 上下文
 */
export function getWebGLContext(canvas: any): WebGLRenderingContextExtended | null {
  try {
    const gl = canvas.getContext('webgl', {
      alpha: true,
      antialias: true,
      depth: false,
      stencil: false,
      preserveDrawingBuffer: false,
      powerPreference: 'high-performance'
    });

    if (!gl) {
      console.warn('[CanvasAdapter] WebGL not supported, trying webgl2');
      return canvas.getContext('webgl2', {
        alpha: true,
        antialias: true,
        depth: false,
        stencil: false,
        preserveDrawingBuffer: false,
        powerPreference: 'high-performance'
      });
    }

    return gl;
  } catch (e) {
    console.error('[CanvasAdapter] Failed to get WebGL context:', e);
    return null;
  }
}

/**
 * Canvas Adapter 类
 */
export class CanvasAdapter {
  private canvas: any;
  private gl: WebGLRenderingContextExtended | null = null;
  private width: number;
  private height: number;

  constructor(options: CanvasAdapterOptions) {
    const { canvasId, width = 375, height = 667, type = 'webgl' } = options;

    // 创建离屏 canvas
    this.canvas = wx.createCanvas(canvasId, { type });

    // 设置尺寸
    this.width = width;
    this.height = height;
    this.canvas.width = width;
    this.canvas.height = height;

    // 获取 WebGL 上下文
    if (type === 'webgl' || type === 'webgl2') {
      this.gl = this.getContext(type);
    }
  }

  getContext(type: string): WebGLRenderingContextExtended | null {
    try {
      return this.canvas.getContext(type, {
        alpha: true,
        antialias: true,
        depth: false,
        stencil: false,
        preserveDrawingBuffer: false,
        powerPreference: 'high-performance'
      });
    } catch (e) {
      console.error('[CanvasAdapter] getContext error:', e);
      return null;
    }
  }

  getGL(): WebGLRenderingContextExtended | null {
    return this.gl;
  }

  getCanvas(): any {
    return this.canvas;
  }

  getWidth(): number {
    return this.width;
  }

  getHeight(): number {
    return this.height;
  }

  setSize(width: number, height: number): void {
    this.width = width;
    this.height = height;
    this.canvas.width = width;
    this.canvas.height = height;
  }

  /**
   * 渲染完成回调
   */
  draw(callback?: () => void): void {
    if (this.canvas.draw && callback) {
      this.canvas.draw(callback);
    } else if (callback) {
      callback();
    }
  }
}

export default CanvasAdapter;
